package io.heapy.komok.tech.runtime.wrappers

import io.heapy.komok.tech.logging.Level

/**
 * Logs each call to the annotated `suspend` method (or every method, on a service type):
 * entry, timed exit, and failure. Generated by the Komok runtime KSP processor into a
 * produced-value decorator; no reflection.
 *
 * The wrapper context is not static: an annotated method must declare
 * `context(_: LoggingContext)` (before the `@Metric` context parameter, if any), and the
 * caller provides the `LoggingContext` at the call site. Only the logger name is derived
 * statically from the service type.
 *
 * Outermost of the production wrapper chain: `@Log` -> `@Metric` -> `@Retry` -> delegate.
 */
@Target(AnnotationTarget.FUNCTION, AnnotationTarget.CLASS)
@Retention(AnnotationRetention.BINARY)
annotation class Log(
    val level: Level = Level.DEBUG,
    val includeResult: Boolean = true,
    val includeDuration: Boolean = true,
)
